    """Process a 3x3 block according to the hypothesized rule"""
    block = [grid[i_start + ri][j_start : j_start + 3] for ri in range(3)]

    # Count all colors
    counts = {}
    for row in block:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1

    total = sum(counts.values())

    if len(counts) == 1:
        # All same color
        return list(counts.keys())[0]
    elif max(counts.values()) == 8:
